<?php
require '../PRACTICAL-8/db.php'; $db=db(); $message=''; $type='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; if($action==='save'){ $id=(int)($_POST['id']??0);$name=trim($_POST['name']);$email=trim($_POST['email']);$course=trim($_POST['course']); if($id){$st=$db->prepare('UPDATE students SET name=?,email=?,course=? WHERE id=?');$st->bind_param('sssi',$name,$email,$course,$id);}else{$st=$db->prepare('INSERT INTO students(name,email,course) VALUES(?,?,?)');$st->bind_param('sss',$name,$email,$course);} if($st->execute()){ $type='success';$message='Student saved.';}else{$type='error';$message='Unable to save student (email may be duplicate).';}}
elseif($action==='delete'){ $id=(int)$_POST['id'];$st=$db->prepare("UPDATE students SET status='Inactive' WHERE id=?");$st->bind_param('i',$id);$st->execute();$type='success';$message='Student marked inactive.';}}
$q='%'.($_GET['q']??'').'%';$course=($_GET['course']??'All'); $sql='SELECT * FROM students WHERE (name LIKE ? OR email LIKE ? OR course LIKE ?)';$params='sss';$values=[$q,$q,$q]; if($course!=='All'){ $sql.=' AND course=?';$params.='s';$values[]=$course;} $sql.=' ORDER BY id DESC';$st=$db->prepare($sql);$bindArgs=[];$bindArgs[]=&$params;foreach($values as $key=>$value){$bindArgs[]=&$values[$key];}$st->bind_param(...$bindArgs);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);
$courses=$db->query('SELECT DISTINCT course FROM students ORDER BY course')->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../PRACTICAL-7/style.css"><title>Student CRUD</title></head><body><main class="box"><h1>Student Management</h1><?php if($message):?><div class="<?= $type ?>"><?= htmlspecialchars($message)?></div><?php endif;
?><form method="get"><label>Search<input name="q" value="<?= htmlspecialchars($_GET['q']??'') ?>"></label><label>Course<select name="course"><option>All</option><?php foreach($courses as $c):?><option <?= $course==$c['course']?'selected':'' ?>><?= htmlspecialchars($c['course']) ?></option><?php endforeach?></select></label><button>Search</button></form>
<p><a href="export_csv.php">Download Student CSV</a></p><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="studentId"><label>Name<input name="name" id="studentName" required></label><label>Email<input type="email" name="email" id="studentEmail" required></label><label>Course<input name="course" id="studentCourse" required></label><button>Save Student</button></form>
<table><tr><th>Name</th><th>Email</th><th>Course</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?= htmlspecialchars($r['name'])?></td><td><?= htmlspecialchars($r['email'])?></td><td><?= htmlspecialchars($r['course'])?></td><td><?= htmlspecialchars($r['status'])?></td><td><button type="button" onclick='editStudent(<?= htmlspecialchars(json_encode($r),ENT_QUOTES) ?>)'>Edit</button><form method="post" onsubmit="return confirm('Mark this student inactive?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="delete">Delete</button></form></td></tr><?php endforeach?></table></main><script>function editStudent(r){studentId.value=r.id;studentName.value=r.name;studentEmail.value=r.email;studentCourse.value=r.course}</script></body></html>
